export interface UnifiedQuestion {
  id: string;
  question: string;
  answers: { id: string; text: string }[];
  correctAnswer: string;
  explanation: string;
  category: string;
  reward: number;
}

type QuestionOverride = Pick<UnifiedQuestion, "question" | "answers" | "explanation" | "category">;

const fromQuiz: UnifiedQuestion[] = quizQuestions.map((q) => ({
  id: q.id,
  question: q.question,
  answers: q.answers,
  correctAnswer: q.correctAnswer,
  explanation: q.retryMessage,
  category: q.category,
  reward: q.reward,
}));

const fromChallenge: UnifiedQuestion[] = challengeQuestions.map((q) => ({
  id: q.id,
  question: q.question,
  answers: q.answers,
  correctAnswer: q.correctAnswer,
  explanation: q.explanation,
  category: "Deep Dive",
  reward: q.reward,
}));

